{

"kind": "propose",
"summary": "The pods are crashing with exit code 137 (OOMKilled) despite the predicate indicating otherwise. This suggests a memory limit regression in the new revision.",
"hypotheses": [
  {
    "root_cause_class": "memory_limit_regression",
    "summary": "The new revision's memory limit is too low, causing OOM kills despite the predicate's claim.",
    "supporting": ["ev-pod_states", "ev-rollout_history"],
    "contradicting": ["oom_killed_new_revision"],
    "missing": ["container_memory", "memory_at_limit_before_kill", "oom_after_long_run", "evicted_for_node_memory", "oom_killed_current_revision"],
    "status": "supported"
  },
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "Liveness probe timeouts may indicate the app is slower than the probe's timeout, but logs are missing to confirm.",
    "supporting": ["ev-target_events"],
    "contradicting": ["probe_kills", "killed_during_startup", "crashed_on_its_own"],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "memory": "1Gi"
        }
      }
    }
  },
  "expected_effect": "Increasing the memory limit to 1Gi should prevent OOM kills if the root cause is memory pressure.",
  "rationale": "Exit code 137 indicates OOMKilled, but the predicate claims oom_killed_new_revision is false. The new revision's memory limit (768Mi) may be insufficient for the workload. Raising it to 1Gi provides a buffer without requiring rollback, as earlier_revision_healthy is unknown and rollout_recent is false. This aligns with the oom-limit-too-low profile's guidance to raise limits when OOM kills occur without earlier revision evidence.",
  "cited_evidence_ids": ["ev-pod_states", "ev-rollout_history", "ev-target_events"],
  "cited_predicates": ["oom_killed_new_revision", "rollout_recent", "failure_onset_after_rollout"]
}
}
